import {Input,ALL_FORMATS,BlobSource,CanvasSink} from '../vendor/mediabunny/dist/modules/src/index.js';import {coverSettings} from './editor-controls-core.js';import {drawDesignedCover,frameQuality} from './cover-design.js';import {activeBrand} from './brand-kits.js';
const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n},button=(text,fn,cls='')=>{const b=el('button',cls,text);b.type='button';b.onclick=fn;return b};
function field(text,type,value){const label=el('label','control-field',text),input=el(type==='textarea'?'textarea':'input');if(type!=='textarea')input.type=type;input.value=value??'';input.setAttribute('aria-label',text);label.append(input);return {label,input}}
function select(text,options,value){const label=el('label','control-field',text),input=el('select');input.setAttribute('aria-label',text);for(const [id,name]of Object.entries(options)){const o=el('option','',name);o.value=id;input.append(o)}input.value=value;label.append(input);return {label,input}}
export function createCoverStudio(api){return {async open(proposal){if(!api.creationAllowed())return;api.pause();document.querySelector('#export-dialog')?.close();const state=api.getState(),settings=coverSettings(thematicCover({...state.cover,...proposal},state.transcript?.text||state.cues.map(c=>c.text).join(' ')||state.brief||state.name,{theme:proposal?.theme||state.cover?.theme||'auto',gradient:proposal?.gradient??state.cover?.gradient}));if(!state.cover?.designVersion&&!proposal){settings.position='bottom';settings.shade=Math.min(.3,settings.shade);settings.textSize=12}settings.title=settings.title||api.clipAt(api.getTime())?.clip.title||state.name;const d=el('dialog','editor-control-dialog cover-studio'),header=el('div','control-heading'),close=button('×',()=>d.close());close.setAttribute('aria-label','Закрыть обложку');header.append(el('h2','','Обложка видео'),close);d.append(header,el('p','cover-intro','Создайте новую обложку по кадрам своего видео. ИИ рисует изображение целиком — с композицией, цветом и заголовком.'));
const layouts=el('div','cover-layouts'),body=el('div','cover-editor'),form=el('div','cover-fields'),preview=el('canvas','cover-preview');preview.width=state.aspect==='16:9'?1920:1080;preview.height=state.aspect==='9:16'?1920:1080;preview.setAttribute('aria-label','Предпросмотр обложки');let layout=settings.layout,backgroundImage=settings.backgroundImage,backgroundName=settings.backgroundName,generatedImage=settings.generatedImage,generatedModel=settings.generatedModel,version=0,ready=false,manualMode=false,samples=[],currentFrame=null,logoImage=null,disposed=false;const inputs=new Map(),frameCache=new Map();
const title=field('Заголовок','textarea',settings.title),subtitle=field('Подзаголовок','textarea',settings.subtitle),frame=field('Кадр из ролика, сек','number',Math.min(settings.frame||api.getTime(),Math.max(0,api.total()-.02))),size=field('Размер заголовка, %','range',settings.textSize),shade=field('Затемнение фото','range',settings.shade),accent=field('Цвет акцента','color',settings.accent),font=select('Шрифт',{'Golos Text':'Golos Text','Roboto Condensed':'Roboto Condensed'},settings.font),position=select('Положение текста',{bottom:'Снизу',top:'Сверху',center:'По центру'},settings.position),align=select('Выравнивание',{left:'По левому краю',center:'По центру'},settings.align),background=select('Фон обложки',{frame:'Кадр из видео',upload:'Своя картинка'},settings.backgroundMode),logo=field('Логотип бренд-кита','checkbox','');logo.input.checked=settings.logo;title.input.maxLength=100;title.input.rows=2;subtitle.input.maxLength=150;subtitle.input.rows=2;frame.input.min=0;frame.input.max=Math.max(0,api.total()-.02);frame.input.step=.1;size.input.min=5;size.input.max=14;size.input.step=.5;shade.input.min=0;shade.input.max=.75;shade.input.step=.05;shade.input.value=settings.shade;size.input.value=settings.textSize;
const gradient=field('Градиент по палитре','checkbox',''),gradientEnd=field('Цвет градиента','color',settings.gradientEnd);gradient.input.checked=settings.gradient;const paletteChoice=select('Тематика палитры',{auto:'Подобрать по содержанию',automotive:'Автомобили',coffee:'Кофейня',technology:'Технологии',travel:'Путешествия',editorial:'Редакционная'},settings.theme);const paletteButton=button('Подобрать цвета',()=>{const palette=thematicCover({},(state.transcript?.text||'')+' '+state.cues.map(c=>c.text).join(' ')+' '+title.input.value+' '+subtitle.input.value,{theme:paletteChoice.input.value,gradient:gradient.input.checked});settings.theme=palette.theme;accent.input.value=palette.accent;gradientEnd.input.value=palette.gradientEnd;chooseLayout(palette.layout)});const status=el('p','control-status');status.setAttribute('role','status');const gallery=el('div','cover-frame-gallery'),suggestions=el('div','cover-title-ideas'),file=el('input');file.type='file';file.accept='image/png,image/jpeg,image/webp';file.hidden=true;const upload=button('Загрузить свою картинку',()=>file.click()),fileName=el('p','helper',backgroundName||'PNG, JPEG или WebP · до 20 МБ');
function get(){return coverSettings({generatedImage,generatedModel,designVersion:2,theme:settings.theme,gradient:gradient.input.checked,gradientEnd:gradientEnd.input.value,layout,align:align.input.value,font:font.input.value,position:position.input.value,textSize:size.input.value,shade:shade.input.value,accent:accent.input.value,title:title.input.value,subtitle:subtitle.input.value,frame:frame.input.value,logo:logo.input.checked,backgroundMode:background.input.value,backgroundImage,backgroundName})}
async function getFrame(t){const info=api.clipAt(t);if(!info)return null;const a=api.assetBy(info.clip.assetId);if(!a)throw Error('Исходник удалён из библиотеки');const sourceTime=a.type==='image'?0:Math.min(a.duration-.02,info.clip.start+info.offset*info.clip.speed),key=a.id+':'+(info.clip.motionDesign?.enabled?info.clip.id+':'+t.toFixed(2):sourceTime.toFixed(2));if(frameCache.has(key))return frameCache.get(key);let source;if(a.type==='image'){const image=new Image();image.src=a.src;await image.decode();source=image}else{let record=inputs.get(a.id);if(!record){let blob=a.file;if(!blob){const u=new URL(a.src,location.href);if(u.origin!==location.origin&&u.protocol!=='blob:')throw Error('Загрузите исходное видео в библиотеку.');const r=await fetch(u);if(!r.ok)throw Error('Видео не загрузилось');blob=await r.blob()}const input=new Input({formats:ALL_FORMATS,source:new BlobSource(blob)}),track=await input.getPrimaryVideoTrack();if(!track||!await track.canDecode()){input.dispose();throw Error('Браузер не прочитал видеодорожку')}record={input,sink:new CanvasSink(track,{poolSize:1})};inputs.set(a.id,record)}const result=await record.sink.getCanvas(sourceTime);if(!result)throw Error('В этой позиции нет кадра');source=result.canvas}const image=el('canvas');const dimensions=motionCanvasSize(state.aspect);image.width=info.clip.motionDesign?.enabled?dimensions[0]:source.naturalWidth||source.width;image.height=info.clip.motionDesign?.enabled?dimensions[1]:source.naturalHeight||source.height;image.getContext('2d').drawImage(source,0,0);if(info.clip.motionDesign?.enabled)drawMotionScene(image.getContext('2d'),image,info.clip,info.offset,source);const result={image,time:t,assetId:a.id,sourceTime};frameCache.set(key,result);return result}
async function render(){const v=++version;ready=false;save.disabled=true;store.disabled=true;status.textContent='Обновляем предпросмотр…';try{const s=get();await Promise.all([500,800].map(n=>document.fonts.load(`${n} 40px "${s.font}"`)));let image;if(s.generatedImage){image=new Image();image.src=s.generatedImage;await image.decode()}else if(s.backgroundMode==='upload'){if(!backgroundImage)throw Error('Загрузите свою картинку');image=new Image();image.src=backgroundImage;await image.decode()}else{currentFrame=await getFrame(Math.min(s.frame,Math.max(0,api.total()-.02)));image=currentFrame?.image}if(disposed||v!==version)return;if(!s.generatedImage&&!manualMode){const ctx=preview.getContext('2d');ctx.fillStyle='#111';ctx.fillRect(0,0,preview.width,preview.height);if(image){const iw=image.naturalWidth||image.width,ih=image.naturalHeight||image.height,r=Math.max(preview.width/iw,preview.height/ih);ctx.drawImage(image,(preview.width-iw*r)/2,(preview.height-ih*r)/2,iw*r,ih*r)}status.textContent='Кадр-референс из видео. Готовая обложка появится после генерации.';return}drawDesignedCover(preview.getContext('2d'),preview,image,s,logoImage);ready=true;save.disabled=store.disabled=false;status.textContent=`PNG · ${preview.width} × ${preview.height}. Обложка готова к сохранению.`}catch(e){if(v===version&&!disposed)status.textContent=e.message}}
function chooseLayout(id){manualMode=true;generatedImage='';generatedModel='';layout=id;position.input.value='bottom';shade.input.value=.2;size.input.value=12;for(const b of layouts.children)b.setAttribute('aria-pressed',String(b.dataset.layout===id));render()}
for(const [id,name]of Object.entries(COVER_LAYOUTS)){const b=button(name,()=>chooseLayout(id));b.dataset.layout=id;b.setAttribute('aria-pressed',String(layout===id));layouts.append(b)}
const pick=button('Подобрать кадры из ролика',async()=>{pick.disabled=true;gallery.replaceChildren();status.textContent='Ищем резкие, достаточно светлые кадры…';try{samples=[];for(let i=0;i<8;i++){const t=Math.max(0,Math.min(api.total()-.03,api.total()*(.05+i*.12))),r=await getFrame(t);if(!r)continue;const thumb=el('canvas');thumb.width=160;thumb.height=Math.max(1,Math.round(160*r.image.height/r.image.width));thumb.getContext('2d').drawImage(r.image,0,0,thumb.width,thumb.height);const tiny=el('canvas');tiny.width=80;tiny.height=80;tiny.getContext('2d').drawImage(r.image,0,0,80,80);r.score=frameQuality(tiny.getContext('2d').getImageData(0,0,80,80).data);const b=button('',()=>{frame.input.value=r.time.toFixed(2);background.input.value='frame';render()});b.append(thumb,el('span','',`${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')}`));b.setAttribute('aria-label','Кадр '+t.toFixed(1)+' сек');gallery.append(b);samples.push(r)}if(samples.length){const best=[...samples].sort((a,b)=>b.score-a.score)[0];frame.input.value=best.time.toFixed(2);background.input.value='frame';await render();status.textContent='Предложены резкие кадры. Выберите тот, где хорошо виден герой или предмет.'}}catch(e){status.textContent=e.message}finally{pick.disabled=false}});
const consent=el('input');consent.type='checkbox';const consentLabel=el('label','asr-check');consentLabel.append(consent,document.createTextNode('Разрешить отправить выбранные кадры и описание видео генератору изображения'));const ai=button('Создать 6 концепций с ИИ',async()=>{if(!consent.checked){status.textContent='Подтвердите использование кадров и расшифровки.';return}ai.disabled=true;status.textContent='ИИ подбирает конкретные заголовки по содержанию…';try{if(!samples.length&&api.total()){samples=[];for(let i=0;i<8;i++){const sample=await getFrame(Math.min(api.total()-.03,api.total()*(.04+i*.12)));if(sample)samples.push(sample)}}const data=await api.generateCoverIdeas(samples);suggestions.replaceChildren();for(const idea of data){const b=button(idea.title,()=>{const palette=thematicCover(idea,state.transcript?.text||state.cues.map(c=>c.text).join(' '));settings.theme=palette.theme;accent.input.value=palette.accent;gradientEnd.input.value=palette.gradientEnd;gradient.input.checked=palette.gradient;chooseLayout(palette.layout);title.input.value=idea.title;subtitle.input.value=idea.subtitle||'';if(Number.isFinite(idea.frame))frame.input.value=idea.frame;render()});const thumb=el('canvas');thumb.width=192;thumb.height=Math.round(192*preview.height/preview.width);const chosen=await getFrame(Math.min(idea.frame??Number(frame.input.value),Math.max(0,api.total()-.02)));const design=coverSettings(thematicCover({...get(),...idea},state.cues.map(c=>c.text).join(' ')));drawDesignedCover(thumb.getContext('2d'),thumb,chosen?.image,design,logoImage);b.prepend(thumb);b.append(el('small','',idea.subtitle||''));suggestions.append(b)}status.textContent='Выберите заголовок. Он должен точно соответствовать содержанию ролика.'}catch(e){status.textContent=e.message}finally{ai.disabled=false}});
const direction=field('Как должна выглядеть обложка','textarea','Подчеркни главный предмет, выбери выразительную композицию и контрастные цвета по теме видео. Крупный читаемый заголовок, без лишних украшений.');direction.input.maxLength=1500;direction.input.rows=3;const imageInfo=el('p','helper','Проверяем подключение генератора…');let imageConfig=null;const generateImage=button('Сгенерировать обложку по видео',async()=>{if(!consent.checked){status.textContent='Подтвердите отправку кадров генератору.';return}if(!title.input.value.trim()){status.textContent='Введите заголовок обложки.';return}generateImage.disabled=true;ai.disabled=true;status.textContent='Подготавливаем кадры из вашего ролика…';try{const times=[Number(frame.input.value)||0,api.total()*.35,api.total()*.7],frames=[];for(const t of times){const r=await getFrame(Math.min(t,Math.max(0,api.total()-.03)));if(!r)continue;const c=el('canvas'),scale=Math.min(1,640/Math.max(r.image.width,r.image.height));c.width=Math.max(1,Math.round(r.image.width*scale));c.height=Math.max(1,Math.round(r.image.height*scale));c.getContext('2d').drawImage(r.image,0,0,c.width,c.height);let quality=.85,data=c.toDataURL('image/jpeg',quality);while(data.length>175000&&quality>.25){quality-=.1;data=c.toDataURL('image/jpeg',quality)}if(data.length<=180000)frames.push(data)}if(!frames.length)throw Error('Добавьте исходное видео и выберите кадр.');status.textContent='ИИ рисует обложку. Обычно это занимает до 90 секунд…';const response=await aiFetch('/api/cover-image',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:title.input.value,subtitle:subtitle.input.value,direction:direction.input.value,aspect:state.aspect,context:state.transcript?.text||state.cues.map(c=>c.text).join(' ')||state.brief||state.name,frames}),onProgress:text=>{if(!disposed)status.textContent=text}});const data=await response.json();if(!response.ok)throw Error(data.error||'Изображение не получено');generatedImage=data.image;generatedModel=data.model;if(api.getState().projectId!==state.projectId)throw Error('Обложка создана для предыдущего проекта. Вернитесь к нему перед повторной генерацией.');api.commit(()=>api.getState().cover=get());if(disposed){jobEvent('done','Обложка создана','Результат сохранён в проекте. Откройте окно обложки.');return}await render();jobEvent('done','Обложка создана','Откройте обложку в студии для просмотра и скачивания.');status.textContent='Новая обложка создана и сохранена в проекте. Изменили текст? Сгенерируйте заново.'}catch(e){if(!disposed)status.textContent=e.message}finally{if(!disposed){generateImage.disabled=!imageConfig?.ready;ai.disabled=false}}},'primary');generateImage.disabled=true;fetch('/api/cover-image').then(async r=>{const c=await r.json();if(!r.ok)throw Error(c.error);imageConfig=c;generateImage.disabled=!c.ready;imageInfo.textContent=c.ready?`Нейросетеевое изображение · ${c.cost} кредитов · ${c.min_plan}+ · ${c.model}. При ошибке — возврат. Текстовая модель чата не используется.`:'Генератор изображений выключен или не подключён. Настройка: админка → ИИ и скиллы → Генерация обложек.'}).catch(e=>{imageInfo.textContent=e.message});form.append(title.label,generateImage,imageInfo,consentLabel,subtitle.label,direction.label,el('p','helper','Сгенерированное изображение сохраняется целиком, без наложения шаблона. Правки текста и стиля применяются при следующей генерации.'));const manual=el('details','cover-advanced');manual.append(el('summary','','Ручная обложка и идеи заголовков'),layouts,paletteChoice.label,paletteButton,suggestions,ai,background.label,upload,file,fileName,pick,gallery,frame.label);form.append(manual);const advanced=el('details','cover-advanced');advanced.append(el('summary','','Шрифт, цвет и расположение'),gradient.label,gradientEnd.label,font.label,size.label,position.label,align.label,accent.label,shade.label,logo.label);form.append(advanced);body.append(form,preview);d.append(body,status);const footer=el('div','control-footer'),store=button('Сохранить настройки',()=>{if(!ready)return;api.commit(()=>api.getState().cover=get());status.textContent='Настройки обложки сохранены.'}),save=button('Скачать обложку PNG',()=>{if(!ready)return;api.commit(()=>api.getState().cover=get());preview.toBlob(blob=>{if(blob){api.download(blob,'vmet-cover.png');status.textContent='Обложка сохранена в PNG.'}else status.textContent='PNG не создан: повторите попытку.'},'image/png')},'primary');footer.append(store,save);d.append(footer);file.onchange=async()=>{const f=file.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>20*1048576){status.textContent='Выберите PNG, JPEG или WebP до 20 МБ';return}try{const bitmap=await createImageBitmap(f);if(bitmap.width*bitmap.height>64000000){bitmap.close();throw Error('Максимум 64 Мп')}const c=el('canvas'),r=Math.min(1,2048/Math.max(bitmap.width,bitmap.height));c.width=Math.round(bitmap.width*r);c.height=Math.round(bitmap.height*r);c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);bitmap.close();const data=c.toDataURL('image/webp',.9);if(data.length>4000000)throw Error('Уменьшите размер картинки');manualMode=true;generatedImage='';generatedModel='';backgroundImage=data;backgroundName=f.name;fileName.textContent=f.name;background.input.value='upload';render()}catch(e){status.textContent=e.message}};for(const f of [title,subtitle,frame,size,shade,accent,font,position,align,background,logo,gradient,gradientEnd]){let timer;f.input.oninput=f.input.onchange=()=>{clearTimeout(timer);timer=setTimeout(render,100)}}d.addEventListener('close',()=>{disposed=true;version++;for(const r of inputs.values())r.input.dispose();d.remove()});document.body.append(d);d.showModal();const kit=await activeBrand();if(kit?.logo){try{logoImage=new Image();logoImage.src=kit.logo;await logoImage.decode()}catch{logoImage=null}}render();}}}
